window.STORY_CHAPTERS["c1a3959eaf12e5c13"]={"id":"c1a3959eaf12e5c13","lines":[{"uid":"talk.vc.home_time_subtilizer_4#originalText","id":"talk.vc.home_time_subtilizer_4","speaker":{"ja":"サトライザー"},"text":{"ja":"粗末な食事よりは、ワインで腹を満たした方がマシか……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_subtilizer_5#originalText","id":"talk.vc.home_time_subtilizer_5","speaker":{"ja":"サトライザー"},"text":{"ja":"ダークテリトリーは広大だなこの世界が我が手中に、と思うと悪い気はせん"},"kind":"dialogue"},{"uid":"talk.vc.home_time_subtilizer_7#originalText","id":"talk.vc.home_time_subtilizer_7","speaker":{"ja":"サトライザー"},"text":{"ja":"早く、この世界のフラクトライトを思うさま味わってみたいものだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_subtilizer_8#originalText","id":"talk.vc.home_time_subtilizer_8","speaker":{"ja":"サトライザー"},"text":{"ja":"酒は多少ましな物が置いてあるようだな。悪くない"},"kind":"dialogue"},{"uid":"talk.vc.home_time_subtilizer_10#originalText","id":"talk.vc.home_time_subtilizer_10","speaker":{"ja":"サトライザー"},"text":{"ja":"人は夜の闇に恐怖を感じると言うが私には一向に感じられないな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_subtilizer_11#originalText","id":"talk.vc.home_time_subtilizer_11","speaker":{"ja":"サトライザー"},"text":{"ja":"この世界が現実の何倍もの速度で動いているとはこの目で見ても信じられないな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_1#originalText","id":"talk.vc.home_time_suguha_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"早安！真是舒爽的早晨呢～要不要一起晨练？","en":"Good morning! And what a lovely morning it is. Wanna do some training?","ja":"おはよう! 気持ちのいい朝だよー一緒に朝練する? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_2#originalText","id":"talk.vc.home_time_suguha_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"啊哈哈，你的头发太好笑了吧！过来一下，我帮你整理整理。","en":"Hahaha! Whoa, look at that cow lick! Come here, I'll fix it.","ja":"あはは、頭すごいよ! ちょっとこっちきて整えてあげるから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_3#originalText","id":"talk.vc.home_time_suguha_3","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"我人是起来了，但还是很困……感觉又会睡着……","en":"I may be awake, but I'm still sleepy... I just might fall asleep again...","ja":"起きたのはいいけどまだ眠いなあ……二度寝しちゃいそう……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_4#originalText","id":"talk.vc.home_time_suguha_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"我今天中午以后就没有安排了。所以，我们出去玩吧。","en":"I have no plans this afternoon, so let's go out somewhere!","ja":"今日は午後から予定ないんだだから、どこかに遊びに行こうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_5#originalText","id":"talk.vc.home_time_suguha_5","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"中午一起吃饭吧。妈妈做的便当有两份呢！","en":"Wanna have lunch together? Mom made enough for both of us!","ja":"お昼、一緒に食べよ? お母さんのお弁当ふたり分あるから! "},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_6#originalText","id":"talk.vc.home_time_suguha_6","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"啊，在睡午觉……好～我也一起睡吧！","en":"Oh! Look who's taking a nap... Fine! Two can play at that game.","ja":"あ、お昼寝してる……よーし、あたしも寝ちゃおう! "},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_7#originalText","id":"talk.vc.home_time_suguha_7","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"今天一整天都在训练，真是累死我了……累到我想直接睡觉了。","en":"I spent the whole day training, and I'm exhausted. I could fall asleep standing up!","ja":"今日、一日中稽古だったからもうクタクタ……このまま寝ちゃいたいくらい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_8#originalText","id":"talk.vc.home_time_suguha_8","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"呼～洗了澡后全身清爽！","en":"Ahhh, nothing is more refreshing than a good bath!","ja":"はあー、お風呂でさっぱりした! "},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_9#originalText","id":"talk.vc.home_time_suguha_9","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"晚上就是要保养竹刀。这是很重要的道具，所以得好好保养才行。","en":"I'll be polishing my bamboo sword tonight. I have to give it some love, since it's so special to me.","ja":"夜は、竹刀の手入れをするの大切な道具だから、ちゃんと磨いてあげないと"},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_10#originalText","id":"talk.vc.home_time_suguha_10","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"在半夜醒过来，就会让我有点不安。所以我才来看看你的。","en":"I always feel anxious when I wake up in the middle of the night. That's why I always come to see you...","ja":"夜中目が覚めるとちょっと不安になるんだだから、こうやって顔を見に来るの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_11#originalText","id":"talk.vc.home_time_suguha_11","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"再不去睡的话，明天早上会很痛苦的。那么，晚安了。","en":"We'd better go to sleep soon, or tomorrow's gonna suck. Well, goodnight.","ja":"そろそろ寝ないと、明日の朝がきついんだそれじゃ、おやすみなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_12#originalText","id":"talk.vc.home_time_suguha_12","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"抱歉，吵醒你了吗？因为我有点想看你的睡脸……对不起喔。","en":"Sorry, did I wake you? Sorry, I was just watching you sleep, that's all.","ja":"ごめん、起こしちゃった? ちょっと、寝顔を見てたかったから……ごめんね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_1#originalText","id":"talk.vc.home_time_tiese_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"早安，学长。您已经起床了吗？","en":"Good morning, sir! Were you already awake?","ja":"おはようございます、先輩もう起きておられましたか? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_2#originalText","id":"talk.vc.home_time_tiese_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"呵呵，学长，好大的呵欠喔。","en":"Hehe, oh, what a huge yawn that was.","ja":"ふふ、先輩大きなあくびですね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_3#originalText","id":"talk.vc.home_time_tiese_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天的早餐要不要跟大家一起吃呢？","en":"Would you like to have breakfast with everyone this morning?","ja":"今日の朝食はみんなで一緒に食べませんか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_4#originalText","id":"talk.vc.home_time_tiese_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长的制服是蓝色呢，很适合您。我也用成蓝色的好了……","en":"I love your blue uniform. You look very nice in it. Maybe I should also wear blue...","ja":"先輩の制服は青なんですねとてもお似合いですあたしも、青にしようかな……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_5#originalText","id":"talk.vc.home_time_tiese_5","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天要上神圣术，必须牢记才行……","en":"We have Sacred Arts lessons today. So many incantations to remember...","ja":"今日は神聖術の授業ですしっかり覚えないと……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_6#originalText","id":"talk.vc.home_time_tiese_6","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我和罗妮耶一起做了便当。请尝尝看。","en":"Ronie and I made your lunch. Hope you like it!","ja":"ロニエとふたりで、お弁当を作ったんです召し上がってください"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_7#originalText","id":"talk.vc.home_time_tiese_7","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"虽然已经过了门禁时间，不过是出自学长的指导，所以也没有办法嘛。","en":"It's past curfew, but I had to press on. I couldn't disobey you.","ja":"門限は過ぎてしまいましたが先輩の指導ですから仕方ないですよね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_8#originalText","id":"talk.vc.home_time_tiese_8","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"晚上聊天的时候，阿滋利卡老师不时会……","en":"When we talk late at night, sometimes we annoy Ms. Azurika.","ja":"夜おしゃべりしていると時々アズリカ先生にお叱りを受けてしまうんです……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_9#originalText","id":"talk.vc.home_time_tiese_9","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"接受学长的指导后，我跟罗妮耶会进行模拟战。不过我们有尽量不发出噪音……","en":"Ronie and I are having little mock-fights, the way you taught us. We try to keep them quiet, though.","ja":"先輩に教えていただいたのでロニエと模擬戦をやっていますうるさくしないように、ですけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_10#originalText","id":"talk.vc.home_time_tiese_10","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长也睡不着吗？那么……我可以和您稍微聊聊天吗？","en":"You can't sleep either? Then...would you like to chat for a while?","ja":"先輩も眠れないのですか? それなら……少しおしゃべりしてもいいですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_11#originalText","id":"talk.vc.home_time_tiese_11","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"如果您明天起不来，我会来叫您的。","en":"If you have a difficult time waking tomorrow, I'll come wake you up.","ja":"もし明日の朝辛ければ起こしにうかがいますね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_12#originalText","id":"talk.vc.home_time_tiese_12","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长好像很困呢。谢谢您陪我。","en":"You look sleepy, Mentor. Thanks for staying up with me.","ja":"先輩、眠そうですねあたしに付き合っていただいてありがとうございました"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_child_1#originalText","id":"talk.vc.home_time_tiese_child_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"早安。做好早餐了喔。是我亲手做的。","en":"Good morning. Breakfast is ready. I made it myself.","ja":"おはようございます朝ご飯ができてますよあたしが作ったんです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_child_2#originalText","id":"talk.vc.home_time_tiese_child_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我昨天很努力读书……所以还很困。","en":"The studies from yesterday were tough... I still feel tired.","ja":"昨日はお勉強が大変で……まだ眠いです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_child_4#originalText","id":"talk.vc.home_time_tiese_child_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"因为我从小时候就开始学剑所以我稍微会用剑。虽然也不是很强……","en":"I've been learning ever since I was little, so I can kind of use a sword. Not that well but...","ja":"小さい頃から習っているから剣だけは少し使えるんですそんなに強くはないけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_child_5#originalText","id":"talk.vc.home_time_tiese_child_5","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"出门游玩很开心的。好了，我们走吧！","en":"It'll feel nice to play outside! Let's go!","ja":"外で遊ぶと気持ちいいですよさあ、行きましょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_child_7#originalText","id":"talk.vc.home_time_tiese_child_7","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"天已经黑了。一天真的过得很快。","en":"Let's like it's already dark out. Before you knew it, another day gone.","ja":"もう暗くなっちゃいましたね一日があっという間だなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_child_8#originalText","id":"talk.vc.home_time_tiese_child_8","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"一到晚上就好困，明明我想醒着跟你聊天的……","en":"I'll instantly get tired when it gets dark out. Even though I want to stay up to talk some more...","ja":"夜はすぐ眠くなっちゃうもっとおしゃべりして起きていたいのに……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_child_10#originalText","id":"talk.vc.home_time_tiese_child_10","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"是妖怪出没的时间……但是，如果是善良的妖怪，我觉得一定不会可怕吧。","en":"It's the hour when monsters come out... But, if that monster is nice it's not so scary.","ja":"お化けが出そうな時間……でも、いい人のお化けならきっと怖くないよね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_child_11#originalText","id":"talk.vc.home_time_tiese_child_11","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"不早点睡明天的训练会很辛苦喔。","en":"We need to go to bed early tonight! Tomorrow's training is going to be a tough one!","ja":"早く寝ないと、明日のお稽古が大変ですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_vassago_1#originalText","id":"talk.vc.home_time_vassago_1","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"天亮了……动作都有点缓慢起来了。","en":"Looks like it's daybreak... I'm having a little trouble moving.","ja":"夜が明けちまったか……少し動きにくくなっちまったな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_vassago_2#originalText","id":"talk.vc.home_time_vassago_2","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"到猎物们出没的时间了。好了，今天要进行怎样的狩猎呢。","en":"It's that time of the day when prey are on the move. I wonder what kind of hunt I will do today.","ja":"獲物たちが動き出す時間ださて、今日はどんな狩りにするか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_vassago_4#originalText","id":"talk.vc.home_time_vassago_4","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"在阳光下，这家伙也太显眼了……","en":"This one is a little showy in the daylight...","ja":"日の光の下じゃ、こいつはちょっと目立ちすぎるな……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_vassago_5#originalText","id":"talk.vc.home_time_vassago_5","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"啊啊，头好痛……有人有阿司匹林吗……这里也不可能有人有吧。","en":"My head hurts... Does anyone... have... an aspirin?","ja":"ああ、頭がいてぇ……誰かアスピリン……って持ってるわけねえか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_vassago_7#originalText","id":"talk.vc.home_time_vassago_7","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"终于天黑了吗。这样子容易活动多了。","en":"Looks like it's finally nightfall. We'll be able to move around easier now.","ja":"やっと日が沈んだかこれで動きやすくなるな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_vassago_8#originalText","id":"talk.vc.home_time_vassago_8","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"酒和食物也无法填满这份饥渴……我需要的是血和悲鸣啊。","en":"This alcohol and food won't be enough to satisfy this hunger... I need blood and screams!","ja":"酒やメシじゃ、この飢えはおさまらねぇ……血と叫びが必要なのよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_vassago_10#originalText","id":"talk.vc.home_time_vassago_10","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"在这种时间出来，会遇到恶魔然后被吃掉喔？……比如说会遇到我。","en":"If you go on a walk at this hour you do know that demons will pop out, right? ...For example, someone like me...","ja":"こんな時間に出歩いてると悪魔に出くわしちまうぜ?……たとえば俺とか、な"},"kind":"dialogue"},{"uid":"talk.vc.home_time_vassago_11#originalText","id":"talk.vc.home_time_vassago_11","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"距离日出还有几个小时。在这段时间就能分出胜负吧。","en":"Only a couple of hours before the sun rises. Until then, let's get to it!","ja":"日が昇るまであと数時間それまでが勝負だな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_vector_1#originalText","id":"talk.vc.home_time_vector_1","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"即便迎来早晨，这世界沉重的空气也没有任何改变。","en":"Even in the morning, the foul stench of this world doesn't change."},"kind":"dialogue"},{"uid":"talk.vc.home_time_vector_2#originalText","id":"talk.vc.home_time_vector_2","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"黑暗领域真是名符其实，天亮了也是这么昏暗。","en":"The Dark Territory is just as the name implies. It's a place where even at daybreak, the skies are dimly lit."},"kind":"dialogue"},{"uid":"talk.vc.home_time_vector_4#originalText","id":"talk.vc.home_time_vector_4","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"比起粗茶淡饭，用红酒填饱肚子还比较好吗……","en":"Wine is a better substitute to satisfy your belly, rather than a skimpy meal."},"kind":"dialogue"},{"uid":"talk.vc.home_time_vector_5#originalText","id":"talk.vc.home_time_vector_5","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"黑暗领域很广阔，一想到这个世界已经落入我的手里，这感觉也不错。","en":"The Dark Territory is vast. When I remember that this world is in the palm of my hands, I feel a little better."},"kind":"dialogue"},{"uid":"talk.vc.home_time_vector_7#originalText","id":"talk.vc.home_time_vector_7","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"快点，我想尽情品味这个世界的摇光。","en":"I want to taste the Fluctlight of this world as soon as possible."},"kind":"dialogue"},{"uid":"talk.vc.home_time_vector_8#originalText","id":"talk.vc.home_time_vector_8","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"这里有放一些比较好的酒。不错。","en":"Looks like there's some decent alcohol laying around. Not bad..."},"kind":"dialogue"},{"uid":"talk.vc.home_time_vector_10#originalText","id":"talk.vc.home_time_vector_10","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"听说人们总会对夜里的黑暗感到恐惧，但我从来也没有这种感觉。","en":"They say that man has a fear for the darkness of the night. I don't quiet feel that."},"kind":"dialogue"},{"uid":"talk.vc.home_time_vector_11#originalText","id":"talk.vc.home_time_vector_11","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"就算用这双眼睛来看也不敢相信，这个世界是以现实的几倍速度运行。","en":"Even if I see it with my own eyes, the speed in which this world moves compared to the real world is truly amazing."},"kind":"dialogue"},{"uid":"talk.vc.home_time_volo_1#originalText","id":"talk.vc.home_time_volo_1","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"你应该不是，这么一路睡到现在吧？","en":"I hope you're not seriously sleeping in this late?","ja":"まさかこんな時間まで寝ていたわけではあるまいな?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_volo_4#originalText","id":"talk.vc.home_time_volo_4","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"好了，我差不多该开始进行自主训练了。","en":"Well, time for me to get back to my voluntary training.","ja":"さて、私はそろそろ自主訓練へと向かうことにしよう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_volo_7#originalText","id":"talk.vc.home_time_volo_7","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"一天很短……要用来提升自我实在太短了。","en":"A day is a short period of time. Too short to train oneself.","ja":"一日は短い……自らを鍛え上げるには短すぎるな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_volo_10#originalText","id":"talk.vc.home_time_volo_10","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"……你也在半夜练剑吗？你跟我似乎很像呢。","en":"You like practicing at night, too? We might be more alike than different.","ja":"……お前も夜に剣を振るのか似た者同士、なのかもしれぬな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yui_1#originalText","id":"talk.vc.home_time_yui_1","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"早安！今天也是个美好的早晨呢！","en":"Good morning! What a lovely morning it is.","ja":"おはようございます!今日もいい朝ですね!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yui_2#originalText","id":"talk.vc.home_time_yui_2","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"呵呵，又睡到头发都翘起来了。","en":"Hehe. You have a cowlick.","ja":"ふふ、また寝癖が付いてますよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yui_4#originalText","id":"talk.vc.home_time_yui_4","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"在艾恩葛朗特吃过的饭，现在回想起来还是会觉得非常好吃呢！","en":"The meals we had in Aincrad were so delicious! I can just taste it now...","ja":"アインクラッドで食べたご飯今思い出しても、とってもおいしかったです!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yui_5#originalText","id":"talk.vc.home_time_yui_5","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"爸爸要睡午觉吗？那我也要一起睡！","en":"A nap? Let me join you!","ja":"お昼寝ですか?じゃあ私も一緒に寝ます!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yui_7#originalText","id":"talk.vc.home_time_yui_7","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"爸爸，辛苦你了！今天要休息了吗？","en":"Good work, Dad! Are you finished for the day?","ja":"パパ、お疲れさまでした!今日はもう休むのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yui_10#originalText","id":"talk.vc.home_time_yui_10","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"这种时间还吃东西的话，你会被妈妈骂喔！","en":"If Mom catches you snacking between meals, she'll give you an earful.","ja":"こんな時間にご飯を食べるとママに怒られますよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yui_11#originalText","id":"talk.vc.home_time_yui_11","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"如果睡不着，就跟我说说话吧。","en":"If you're having trouble sleeping, we could talk for a while.","ja":"眠れないのなら、なにかお話をしてください"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuna_1#originalText","id":"talk.vc.home_time_yuna_1","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"早安！呐，你今天要带我去哪里呢！？","en":"Morning! Hey, hey, where are you going to take me today?","ja":"おはよう!ねえねえ、今日はどこに連れて行ってくれるの!?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuna_2#originalText","id":"talk.vc.home_time_yuna_2","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"早上的太阳很让人身心舒畅吧－－！身体和声音好像都觉醒了！","en":"The morning sun feels great! I feel like my body and voice are fully awake!","ja":"朝の太陽って気持ちいいよねー体も声も、目が覚める感じ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuna_4#originalText","id":"talk.vc.home_time_yuna_4","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"咦－－睡午觉？睡掉了多可惜啊！来，我们出门吧～","en":"Ehh, napping? That's such a waste. Come on, let's go out.","ja":"ええー、お昼寝?そんなのもったいないよほら、お出かけしようー"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuna_5#originalText","id":"talk.vc.home_time_yuna_5","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"听说那边会出现很大的怪物耶！呐呐，我们去看看嘛！","en":"I heard that a huge monster appears over there! Hey, hey, let's go and take a look!","ja":"向こうにでっかいモンスターが出るんだって!ねえねえ、見に行ってみようよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuna_7#originalText","id":"talk.vc.home_time_yuna_7","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"夜晚现在才正要开始呢。毕竟你也还不困吧？","en":"Looks like it'll start getting dark soon. You're not tired yet, are you?","ja":"まだまだ夜はこれからだよねだって、まだ眠くないでしょう?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuna_8#originalText","id":"talk.vc.home_time_yuna_8","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"今天好开心喔！明天要叫你带我去哪里好呢～","en":"Today was pretty fun! I wonder where you'll take me tomorrow.","ja":"今日は楽しかったね明日は、どこに連れて行ってもらおうかなー"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuna_10#originalText","id":"talk.vc.home_time_yuna_10","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"在半夜寂静的气氛中，反而会很想尽情唱歌对吧？是不是会被骂啊～","en":"Amongst the silent night skies doesn't it just make you want to sing? I guess it would make people mad...","ja":"夜中のシーンとした空気の中って思いっきり歌いたくなるよね?やっぱり怒られるかなー"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuna_11#originalText","id":"talk.vc.home_time_yuna_11","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"嗯－－，虽然现在就睡有点可惜。但是明天有事还是得睡啊。晚安～","en":"Yeah, it's a bit of a waste, but we have to get some sleep for tomorrow. Good night.","ja":"うーん、ちょっともったいないけど明日のために寝ないとねおやすみなさいー"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_1#originalText","id":"talk.vc.home_time_yuuki_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"早安，我今天俐落地起床了喔！","en":"Good morning! I'm bright-eyed and bushy-tailed!","ja":"おはよう今日はすっきり目が覚めたよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_2#originalText","id":"talk.vc.home_time_yuuki_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"早上一醒来就觉得开心，因为今天肯定也会很愉快的。","en":"Whenever I wake up in the morning, I always feel really excited. That’s because I know it'll be another great day!","ja":"朝、目が覚めるとうれしくなるんだ今日もきっと楽しいぞ、って"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_3#originalText","id":"talk.vc.home_time_yuuki_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"呼哇……今天好困，昨天可能太拼了。","en":"Phew, I really am sleepy today. I think I overexerted myself yesterday.","ja":"ふわあ……今日は眠いなあ昨日頑張りすぎちゃったかも"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_4#originalText","id":"talk.vc.home_time_yuuki_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"今天天气真舒服，我能理解你想午睡的心情。","en":"What a nice day, huh. I can understand why you'd want to take a nap.","ja":"今日は気持ちいいねえお昼寝したくなる気持ちもわかるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_5#originalText","id":"talk.vc.home_time_yuuki_5","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"光是能走在太阳底下，就让我很高兴了。","en":"Just taking a walk under the sun makes you feel so giddy, doesn't it?","ja":"おひさまの下を歩けるってそれだけでウキウキするんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_6#originalText","id":"talk.vc.home_time_yuuki_6","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"肚子饿了啦～要不要吃午餐了？","en":"I'm getting hungry. Let's have some lunch.","ja":"お腹空いてきたなーそろそろお昼ご飯にしない? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_7#originalText","id":"talk.vc.home_time_yuuki_7","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"欸，我们一起洗澡嘛！","en":"Come on, let's take a bath!","ja":"ねえ、お風呂一緒に入ろうよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_8#originalText","id":"talk.vc.home_time_yuuki_8","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"感觉已经开始想睡觉了。也许是白天嗨过头了吧？","en":"I'm already running out of energy. I probably overdid it during the day.","ja":"なんだか、もう眠くなっちゃった昼間飛ばしすぎたかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_9#originalText","id":"talk.vc.home_time_yuuki_9","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"饭后的这种悠闲时光……我最喜欢了。","en":"See, relaxing and hanging out like this after a nice big meal? I live for these moments.","ja":"ご飯食べた後の、こういうゆっくりとした時間……大好きなんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_10#originalText","id":"talk.vc.home_time_yuuki_10","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我不讨厌静谧的夜晚喔。虽然有时候会觉得寂寞就是了。","en":"I don't mind quiet nights. Though I sometimes feel a little lonely.","ja":"静かな夜はキライじゃないよ時々、寂しくなるけどね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_11#originalText","id":"talk.vc.home_time_yuuki_11","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"你醒啦？嘿嘿，我也是。我们来聊个天吧。","en":"Did you wake up? Hehe. Same. Wanna talk for a while?","ja":"目が覚めちゃったの? へへ、ボクもなんだ少しおしゃべりしよっか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_12#originalText","id":"talk.vc.home_time_yuuki_12","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"哈哈，你看起来很困耶。那差不多也该睡觉了。","en":"Haha, you sure look sleepy. Okay, let's turn in.","ja":"はは、眠そうだねそれじゃ、そろそろ休もっか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_zink_1#originalText","id":"talk.vc.home_time_zink_1","speaker":{"cn":"吉克","en":"Zink","ja":"ジンク"},"text":{"cn":"啊，你已经醒啦？真早呢。","en":"Oh, you're awake already? You're sure up early.","ja":"ああ、もう起きてたのか早いな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_zink_4#originalText","id":"talk.vc.home_time_zink_4","speaker":{"cn":"吉克","en":"Zink","ja":"ジンク"},"text":{"cn":"好，来吃午餐吧。","en":"Well, let's have some lunch.","ja":"さあ、昼飯にするか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_zink_7#originalText","id":"talk.vc.home_time_zink_7","speaker":{"cn":"吉克","en":"Zink","ja":"ジンク"},"text":{"cn":"我先睡啰。晚安。","en":"I'm going to bed now. Goodnight.","ja":"俺は先に寝るぜおやすみ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_zink_10#originalText","id":"talk.vc.home_time_zink_10","speaker":{"cn":"吉克","en":"Zink","ja":"ジンク"},"text":{"cn":"……干嘛啦？现在还是半夜耶！","en":"What is it? It's in the middle of the night!","ja":"……なんだよ?まだ夜中じゃないか!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_1#originalText","id":"talk.vc.home_touch_administrator_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"还不退下。照理来说，光是伸手的念头就属重罪了。","en":"Stop that. The mere thought of touching me is already a sin.","ja":"控えなさい本来であれば、手を伸ばそうと考えることすら重罪よ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_2#originalText","id":"talk.vc.home_touch_administrator_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"真拿你没办法……又想要我让你「作梦」吗？","en":"Very well, then. Shall I show you another \"dream\"?","ja":"仕方ないわね……また「夢」を見せてほしいの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_3#originalText","id":"talk.vc.home_touch_administrator_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"我能理解看我的脸看到入迷……但我不准你调皮。","en":"I understand that you are enchanted by my visage. But laying hands upon me is unforgivable.","ja":"私の顔に見惚れるのはわかるけど……オイタは許さないわ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_4#originalText","id":"talk.vc.home_touch_administrator_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"真可惜。金属制成的武器，是伤不了我的。","en":"A pity. Metal weapons are ineffective against me.","ja":"残念ね金属製の武器は、私には通じないの"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_5#originalText","id":"talk.vc.home_touch_administrator_5","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"嗯……我知道了。你帮我拿件衣服穿吧。","en":"Very well, then. Fetch me something to wear.","ja":"ん……わかったわなにか着るものをとって頂戴"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_6#originalText","id":"talk.vc.home_touch_administrator_6","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"真是爱撒娇……你又想要「爱」了吗？","en":"You certainly are needy. Would you like some more \"love\"?","ja":"甘えん坊ね……また「愛」がほしくなったのかしら?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_7#originalText","id":"talk.vc.home_touch_administrator_7","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"和某个小不点天差地远对吧？","en":"You aren't like the other little boys, are you?","ja":"どこぞのちびっことは違うでしょう?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_8#originalText","id":"talk.vc.home_touch_administrator_8","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"……怎么了？你这件事，应该真的有必要劳烦我判断吧？","en":"What is it? You don't really need my judgement, do you?","ja":"……なに?本当に私の判断が必要なことなのでしょうね?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_agil_1#originalText","id":"talk.vc.home_touch_agil_1","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"我只是剃光而已，绝对不是没有头发喔。","en":"I'm not really bald. I just shave every day.","ja":"これは、剃ってるだけだ決して髪がないわけじゃないぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_agil_2#originalText","id":"talk.vc.home_touch_agil_2","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"你垫脚尖也不过这么高啊？如果你想摸我的头，得再长高一点才行啊。","en":"So that's why you stood on tiptoe? Hey, kid, if you wanna touch my head, grow a couple feet first.","ja":"背伸びしてその程度かオレの頭に触りたかったらもうちょっとでかくならないとな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_agil_3#originalText","id":"talk.vc.home_touch_agil_3","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"只有我老婆可以摸我头。","en":"The only person who's allowed to touch my head is my wife.","ja":"オレの頭を触っていいのはかみさんだけだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_agil_4#originalText","id":"talk.vc.home_touch_agil_4","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"还是要锻炼一下身体才行。在虚拟世界里战斗，也是要吃体力的。","en":"You have to keep up with your exercise one way or another. Even VR-fighting requires real strength.","ja":"ある程度は体を鍛えないとな仮想世界で戦うにも体力が必要だ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_agil_5#originalText","id":"talk.vc.home_touch_agil_5","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"你也要记得确认护甲啊，那可是保护性命的重要装备。","en":"You should check your armor, too. It can save your life.","ja":"お前の方も、アーマーは確認しておけよ命を守る大事な装備だ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_agil_8#originalText","id":"talk.vc.home_touch_agil_8","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"怎么？想卖东西啊？我全都会用「适当价格」收购的。","en":"Wanna buy something? I'll give you a fair price on any item.","ja":"なんだ、買い取りか?なんでも「適正価格」で買い取ってやるぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_airy_1#originalText","id":"talk.vc.home_touch_airy_1","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"？怎么了吗？","en":"Hm...? Something wrong?","ja":"?どうかされましたか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_airy_2#originalText","id":"talk.vc.home_touch_airy_2","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"……很不可思议地，我不讨厌您这样对我。","en":"Oddly enough... I don't mind what you're doing.","ja":"……そうされるのは不思議と嫌ではありません"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_airy_3#originalText","id":"talk.vc.home_touch_airy_3","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"请问我的头上，有沾什么东西吗？","en":"Is there something on my head?","ja":"わたくしの頭に、なにかついておりましたでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_airy_4#originalText","id":"talk.vc.home_touch_airy_4","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"我不是很明白，请问那么做您会开心吗？","en":"I don't understand why you're doing that. Is it fun?","ja":"よくわかりませんがそれは楽しいことなのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_airy_5#originalText","id":"talk.vc.home_touch_airy_5","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"……如果再继续，您有可能会抵触禁忌目录。","en":"If you go any further... you may be in defiance of the Taboo Index.","ja":"……それ以上は、禁忌目録に抵触する可能性がございます"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_airy_8#originalText","id":"talk.vc.home_touch_airy_8","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"您有什么吩咐吗？只要是您的吩咐，还请务必让我帮忙。","en":"Do you require my services? I will gladly take on any task you have.","ja":"なにかご用でございますか?あなた様からのご用であればぜひお手伝いさせてください"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_airy_coverall_1#originalText","id":"talk.vc.home_touch_airy_coverall_1","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"？怎么了吗？","en":"Hm...? Something wrong?","ja":"?どうかされましたか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_airy_coverall_2#originalText","id":"talk.vc.home_touch_airy_coverall_2","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"……很不可思议地，我不讨厌您这样对我。","en":"Oddly enough... I don't mind what you're doing.","ja":"……そうされるのは不思議と嫌ではありません"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_airy_coverall_3#originalText","id":"talk.vc.home_touch_airy_coverall_3","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"请问我的头上，有沾什么东西吗？","en":"Is there something on my head?","ja":"わたくしの頭に、なにかついておりましたでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_airy_coverall_4#originalText","id":"talk.vc.home_touch_airy_coverall_4","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"我不是很明白，请问那么做您会开心吗？","en":"I don't understand why you're doing that. Is it fun?","ja":"よくわかりませんがそれは楽しいことなのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_airy_coverall_5#originalText","id":"talk.vc.home_touch_airy_coverall_5","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"……如果再继续，您有可能会抵触禁忌目录。","en":"If you go any further... you may be in defiance of the Taboo Index.","ja":"……それ以上は、禁忌目録に抵触する可能性がございます"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_airy_coverall_8#originalText","id":"talk.vc.home_touch_airy_coverall_8","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"您有什么吩咐吗？只要是您的吩咐，还请务必让我帮忙。","en":"Do you require my services? I will gladly take on any task you have.","ja":"なにかご用でございますか?あなた様からのご用であればぜひお手伝いさせてください"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_1#originalText","id":"talk.vc.home_touch_alice_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"无、无理之徒！居然抚摸集成骑士的头……不、不可原谅！","en":"Impudent dog! How dare you touch the head of an Integrity Knight... You shall pay dearly for this!","ja":"ぶ、無礼な! 整合騎士の頭を撫でるなど……ゆ、許しません! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_2#originalText","id":"talk.vc.home_touch_alice_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你那只手，是想做什么？我的眼睛已经不要紧了。……那时候让你担心了。","en":"Where do you think you're putting your hand? My eye is fine now. Sorry I worried you earlier.","ja":"なんですか、その手はもう右目は大丈夫です……あの時は心配をかけました"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_3#originalText","id":"talk.vc.home_touch_alice_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我的脑海中，只残存少许妹妹和家人的记忆。但即便只有这些，我还是很开心……","en":"Shadows of my family remain in my memory. That alone satisfies me...","ja":"私の頭の中にも、妹や家族の記憶が残滓として残っていますそれだけでも、うれしいのです……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_4#originalText","id":"talk.vc.home_touch_alice_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"怎么了？你不会又想跟我借手帕吧……真拿你没办法。","en":"What is it? I hope you aren't asking for more money... Inconceivable.","ja":"なんですか? もしかして、また手巾を貸してほしいのですか……まったく"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_5#originalText","id":"talk.vc.home_touch_alice_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……要我和你交手吗？正合我意。我会打到让你认输。","en":"You wish to spar with me? I gladly accept. Prepare to be slashed to the ground.","ja":"……剣の手合わせですか? 望むところです叩き伏せてあげます"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_6#originalText","id":"talk.vc.home_touch_alice_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你这个家伙实在是……我不会再放过你。我要砍了你那只手。","en":"I've had it with you... That's it! I'm cutting off your hand!","ja":"お前というヤツは……もう許しておけませんその手、切り捨てます"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_7#originalText","id":"talk.vc.home_touch_alice_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我是女人，更是一名集成骑士。然而……即便如此，有些事还是该谨守分寸。","en":"I am an Integrity Knight first, woman second. However...there are certain things I cannot do.","ja":"私は女である前に整合騎士ですですが……それにしても、やってはならないことはあります"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_8#originalText","id":"talk.vc.home_touch_alice_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你找我吗？好吧。和你对话，对我而言也是有意义。","en":"You summoned me to talk? Very well. Talking to you is beneficial to me as well.","ja":"呼びましたか? いいでしょう。お前と話すのは私にとっても有意義ですから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_child_1#originalText","id":"talk.vc.home_touch_alice_child_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"呵呵，我的头发很漂亮吧？这是我请母亲帮忙梳的呢。","en":"Hehe, my hair's pretty, isn't it? I had my mother comb it for me.","ja":"ふふ、きれいな髪でしょお母様に梳いてもらったんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_child_2#originalText","id":"talk.vc.home_touch_alice_child_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"一直摸我的头……我又不是小孩子了。","en":"Don't pat my head. I'm not a baby.","ja":"頭なでなでなんて……子どもじゃないんだからね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_child_3#originalText","id":"talk.vc.home_touch_alice_child_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"咦，你的手是不是变大啦？……是没什么差啦，我只是有点这么觉得而已！","en":"Oh, did your hands get bigger? I don't really care...it was just a passing thought!","ja":"あれ、手が大きくなった? ……別になんでもないけどちょっとそう思っただけ! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_child_4#originalText","id":"talk.vc.home_touch_alice_child_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"嗯？你叫我吗？","en":"Hm? You called me?","ja":"ん、呼んだ? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_child_5#originalText","id":"talk.vc.home_touch_alice_child_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"搔痒游戏对吧！我也是不会输的！","en":"A tickle fight, eh? Oh, I'm very competitive!","ja":"くすぐりごっこね! 私だって負けないんだから! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_child_6#originalText","id":"talk.vc.home_touch_alice_child_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"喂，暂停啦！你知不知道自己在摸哪里啊！？","en":"W-whoa, there! Do you realize where you're touching?","ja":"ちょ、ちょっと! どこさわってるのかわかってるの!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_child_7#originalText","id":"talk.vc.home_touch_alice_child_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"不可以那么做啦。真是的，男孩子就是这样，讨厌鬼……","en":"Don't do that. Honestly! Boys can be so gross.","ja":"そういうの、ダメよまったく、これだから男の子って、もう……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_child_8#originalText","id":"talk.vc.home_touch_alice_child_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"呀，有虫爬到我身上？快帮我拿掉！","en":"Eek! There's a bug on me! Get it off!","ja":"きゃっ、虫がついてる? 早く取って! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alicia_1#originalText","id":"talk.vc.home_touch_alicia_1","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"喵哈哈，耳朵很痒耶！","en":"Haha, not the ears! That tickles!","ja":"にゃはは、耳はくすぐったいヨ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alicia_2#originalText","id":"talk.vc.home_touch_alicia_2","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"喵……你摸得我很舒服耶……","en":"Meowww... You’re a great petter!","ja":"にゃああ……キミ、撫でるの上手だネ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alicia_3#originalText","id":"talk.vc.home_touch_alicia_3","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"呵呵，这次就换我给你摸摸啰！","en":"Hehehe. Now it's my turn to pet you!","ja":"んふふ、今度はアタシがキミをナデナデしてあげるネ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alicia_4#originalText","id":"talk.vc.home_touch_alicia_4","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"你也很厉害嘛……你应该不会对谁都这样做吧？","en":"Pretty bold moves, coming from you? Though I hope you don't do this to just anyone?","ja":"キミもなかなかやるネ……まさか誰にでもやってるわけじゃないよネ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alicia_5#originalText","id":"talk.vc.home_touch_alicia_5","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"确实是有那──么一点单薄，但又不是大就好！","en":"I'll admit I'm a bit of a shrimp, but size isn't everything!","ja":"確かにちょーーっと寂しいけど大きさだけじゃないんだヨ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alicia_8#originalText","id":"talk.vc.home_touch_alicia_8","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"嗯？什么什么？你要出门吗？","en":"What's up? Going out somewhere?","ja":"ん、なになに?どこかお出かけする?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alphen_1#originalText","id":"talk.vc.home_touch_alphen_1","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alphen_2#originalText","id":"talk.vc.home_touch_alphen_2","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_argo_1#originalText","id":"talk.vc.home_touch_argo_1","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"干嘛啦？脸上画这对胡须的理由……你不是早就知道了？","en":"What? You know why I have whiskers...","ja":"なんだヨこのおヒゲの理由は……知ってるはずダロ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_argo_2#originalText","id":"talk.vc.home_touch_argo_2","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"只要披上兜帽，不知为何就会安下心来。","en":"Wearing a hood makes me feel safer.","ja":"フードをかぶってるとなんか安心するんだヨ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_argo_3#originalText","id":"talk.vc.home_touch_argo_3","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"喂，住手！很痒啦！","en":"Hey, stop! That tickles!","ja":"ちょ、やめろヨ!くすぐったいんだっテバ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_argo_4#originalText","id":"talk.vc.home_touch_argo_4","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"干嘛啦？你想偷情报吗？我才不会让你得逞呢。","en":"What, trying to steal intel from me? Over my dead body!","ja":"なんだヨ、情報でも抜こうっていうのカ?そんなことはさせないゾ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_argo_5#originalText","id":"talk.vc.home_touch_argo_5","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"……你那没大没小的态度，还是一样没变呢。","en":"No respect for personal space, as always. You never change, do you?","ja":"……そういう気安いところは変わらないんダナ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_argo_6#originalText","id":"talk.vc.home_touch_argo_6","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"喂、喂喂……我好歹也算一名淑女……懂吗？","en":"Uh... Whoa. Just, whoa. I'm a lady, you know?","ja":"お、オイオイ……オレっちだってレディ……なんだゾ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_argo_7#originalText","id":"talk.vc.home_touch_argo_7","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"你再继续乱摸，我就要卖了你的「那个」丢脸数据喔！","en":"If you keep touching me, I'm selling that embarrassing piece of intel I have on you. Yeah. \"That\" one.","ja":"それ以上触ったら「あの」恥ずかしいデータ売りさばくヨ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_argo_8#originalText","id":"talk.vc.home_touch_argo_8","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"有新情报吗？那我可是随时欢迎喔。","en":"A new way of finding intel? I'm all ears!","ja":"新しい情報カ?それならいつでも歓迎ダゾ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_1#originalText","id":"talk.vc.home_touch_asuna_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"把头发编到后面这件事啊，等到习惯之后，就会比想像得还要容易。","en":"Braiding my own hair was a lot easier than I thought, once I got the hang of it.","ja":"うしろの編み込みはね慣れちゃえば思ったより簡単にできるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_2#originalText","id":"talk.vc.home_touch_asuna_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呵呵……再多摸摸我嘛。","en":"Hehe... More pats, please?","ja":"ふふ……もっとなでて? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_3#originalText","id":"talk.vc.home_touch_asuna_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"虽然觉得有点痒，但我不讨厌你摸我喔。","en":"That tickles, but I never mind when you touch me.","ja":"ちょっとくすぐったいけど君に撫でられるのいやじゃないよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_4#originalText","id":"talk.vc.home_touch_asuna_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"哇！突然被人碰，我会吓到啦。","en":"Agh?! Warn a girl first before you touch her.","ja":"わっ? いきなり触られたらびっくりしちゃうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_5#originalText","id":"talk.vc.home_touch_asuna_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"下次去买衣服的时候，你可以陪我一起去吗？","en":"Will you come with me the next time I go clothes shopping?","ja":"今度洋服を買いに行く時一緒に来てくれる? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_6#originalText","id":"talk.vc.home_touch_asuna_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"真是的，怎么在这种地方……这样不行喔。","en":"Stop! We're in public...","ja":"もう、こんなところで……ダメ、だよ? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_7#originalText","id":"talk.vc.home_touch_asuna_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"讨厌，你也看一下时间跟场合吧……","en":"This isn't the time or place...","ja":"もう、ちょっとは時と場所を考えてよね……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_8#originalText","id":"talk.vc.home_touch_asuna_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"哎呀，怎么了？哦～我猜你是肚子饿了吧？","en":"Is something wrong? Ohhh, I know. You must be hungry.","ja":"あれ、どうしたの? あ、さてはお腹が空いたのね? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_azurica_1#originalText","id":"talk.vc.home_touch_azurica_1","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"……你是带着什么盘算，才做出这种行为的？","en":"What intentions are motivating your actions?","ja":"……どのような意図でこの行為をしているのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_azurica_2#originalText","id":"talk.vc.home_touch_azurica_2","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"我身上有灰尘吗？不过，让我自己来拍掉就好。","en":"Is there some dust on my clothes? Thanks, but I can remove it myself.","ja":"ホコリでも付いていますか?けれど自分で取れますから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_azurica_3#originalText","id":"talk.vc.home_touch_azurica_3","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"如果你有时间做这种事，就应该挪去修练吧？","en":"If you have time for such antics, why don't you get to your training?","ja":"こんなことをしている時間があるなら修練をしてくるべきでは?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_azurica_4#originalText","id":"talk.vc.home_touch_azurica_4","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"你打算摸哪里？看一下场合吧。","en":"Who do you think you're touching? Just look at yourself.","ja":"どこを触ろうとしているのですか?場をわきまえなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_azurica_5#originalText","id":"talk.vc.home_touch_azurica_5","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"我不会再容忍了。","en":"I will not allow any more of this.","ja":"それ以上は許しません"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_azurica_8#originalText","id":"talk.vc.home_touch_azurica_8","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"你有什么烦恼吗？","en":"Do you need help?","ja":"なにか困りごとですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_bercouli_1#originalText","id":"talk.vc.home_touch_bercouli_1","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"喔，那个动作我看透啦。你的步法还有得练呢。","en":"Easy, tiger, you're telegraphing your next moves. You're underestimating your opponent.","ja":"おっと、その動きは見えてるぜ踏み込みが甘いな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_bercouli_2#originalText","id":"talk.vc.home_touch_bercouli_2","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"怎么，你很在意这道伤吗？伤疤这东西，对男人来说就等同是勋章。","en":"Do my scars concern you? A man's scars are like badges of honor.","ja":"なんだ、この傷が気になるのか?傷なんざ、男にとっては勲章と同じだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_bercouli_3#originalText","id":"talk.vc.home_touch_bercouli_3","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"干嘛啦，没关系啦。这发型就可以了……","en":"Hey, stop it. I like my hair the way it is.","ja":"なんだよ、いいんだよ髪型はこのままで……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_bercouli_5#originalText","id":"talk.vc.home_touch_bercouli_5","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"嗯？怎么了？你想要跟我过招吗？","en":"What's up? You want a practice-duel?","ja":"ん、なんだ?手合わせしてほしいのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_bercouli_8#originalText","id":"talk.vc.home_touch_bercouli_8","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"是是，我知道啦。我会好好工作。","en":"Okay, I get it. I'll get back to work.","ja":"はいはい、わかったよちゃんと仕事するから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_cardinal_1#originalText","id":"talk.vc.home_touch_cardinal_1","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"别看我这样，我可是比你大上何止一百岁。不要把我当小孩子对待。","en":"I may not look it, but I am 100 years your senior. Stop treating me like a child.","ja":"こう見えても、お主より百歳以上は年上じゃ子どものように扱うのはやめい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_cardinal_2#originalText","id":"talk.vc.home_touch_cardinal_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"……被摸头的时候，莫名会有股怀念的感觉明明我就没有记忆","en":"...When someone pats my head, it oddly feels nostalgic. Even though I have no memories of it.","ja":"……頭を撫でられると、不思議と懐かしさを覚えるんじゃ記憶もないのにな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_cardinal_3#originalText","id":"talk.vc.home_touch_cardinal_3","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"个子矮我也无可奈何啊！对于用以附身的肉体，我完全无法加以干涉。","en":"I cannot help being small! I had no say in the vessel I was given to occupy.","ja":"背が小さいのは仕方のないことじゃ!依代になった肉体はわしにはどうすることもできん"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_cardinal_4#originalText","id":"talk.vc.home_touch_cardinal_4","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"人类的温暖……好长一段时间，我一直在梦想着这个。","en":"A human's warmth... I've dreamed of it for so long.","ja":"人の温もり……長い間、わしはそれを夢見てきた"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_cardinal_5#originalText","id":"talk.vc.home_touch_cardinal_5","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我基本上不讨厌被人触碰……但你该对触碰的地方有点分寸。","en":"I don't dislike being touched... Just, choose where you're touching wisely.","ja":"人に触れられるのは基本的に嫌ではないが……触れる場所はわきまえるんじゃな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_cardinal_6#originalText","id":"talk.vc.home_touch_cardinal_6","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"你真的都不怕违背禁忌目录呢。","en":"Seriously, do you not fear the Taboo Index at all?","ja":"本当にお主は禁忌目録に背くことを恐れんのじゃな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_cardinal_7#originalText","id":"talk.vc.home_touch_cardinal_7","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我很清楚！别拿我和亚多米尼史特蕾达的那个相比啦！","en":"I see what this is! Do not compare me to Administrator!","ja":"わかっておる!アドミニストレータのアレと比べるでないわっ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_cardinal_8#originalText","id":"talk.vc.home_touch_cardinal_8","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"怎么？有事找我，就用说的。","en":"What is it? If you need something, use your words.","ja":"なんだ?用があるなら、口で呼べ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_dakira_1#originalText","id":"talk.vc.home_touch_dakira_1","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"这个面甲是我们的羁绊……我绝对会守护到底。","en":"Our visors represent our bond. I will not let you touch mine.","ja":"この面頬は我々の絆……絶対に守り抜きます"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_dakira_2#originalText","id":"talk.vc.home_touch_dakira_2","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"啊……怎、怎么了吗！？","en":"Oh... W-what is the matter?!","ja":"あ……い、いかがされました!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_dakira_3#originalText","id":"talk.vc.home_touch_dakira_3","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"请您用那双手指引我们吧。","en":"Please guide us.","ja":"その手によって我らをお導きください"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_dakira_4#originalText","id":"talk.vc.home_touch_dakira_4","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"……我很开心。我仿佛感受到您的心意了……","en":"I am indeed honored... that your will has been transmitted.","ja":"……うれしく思いますあなたの想いが、伝わって来るようで……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_dakira_5#originalText","id":"talk.vc.home_touch_dakira_5","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"就连这颗心脏，也全都属于您的。","en":"Every part of me, even my heart, belongs to you.","ja":"この心臓も、すべてあなたのものです"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_dakira_8#originalText","id":"talk.vc.home_touch_dakira_8","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"有什么吩咐吗？为了随时都能动身，我已早有准备！","en":"A mission?! We are prepared to depart at a moment's notice!","ja":"ご用命ですか?いつでも出られるよう準備はできております!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_deathgun_1#originalText","id":"talk.vc.home_touch_deathgun_1","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"想要、打探、我的、真实身分，也是没用的。绝对、不知道。","en":"Even if you try looking up who I am it's pointless. You won't find it.","ja":"俺の、正体を、探ろうとしても無駄だ決して、わからない"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_deathgun_2#originalText","id":"talk.vc.home_touch_deathgun_2","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"哼、哼、哼。竟敢、向我、下战帖。下一个、目标、就是你。","en":"Heh heh heh. If you are going to battle me, then my next target will be you.","ja":"ク、ク、ク俺に、バトルを、挑んでくるとは次の、ダーゲットは、お前だ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_deathgun_3#originalText","id":"talk.vc.home_touch_deathgun_3","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"就算、拿下、这个斗篷。也不可能、知道、我的名字。","en":"Removing my hood doesn’t give away my name.","ja":"この、フードを、取ったところで俺の、名前は、わからないぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_deathgun_4#originalText","id":"talk.vc.home_touch_deathgun_4","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"你要、用剑、砍我吗？你觉得、这样、我就会死吗？","en":"Swing a sword at me? Do you really think that’ll kill me?","ja":"剣で、斬るか?それで、俺が死ぬと、思うか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_deathgun_5#originalText","id":"talk.vc.home_touch_deathgun_5","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"那种、弱小的、攻击。连、打到我、都很难。","en":"Even such a dull attack won't hit me.","ja":"そんな、なまくらな、攻撃じゃ俺に、当てることすら、できない"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_deathgun_8#originalText","id":"talk.vc.home_touch_deathgun_8","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"就算、贯穿了、我的胸口。我也不会、死……我和、那边、可不一样……","en":"For example, even if you were to pierce my chest, I won't... die. ...That is a huge difference...","ja":"たとえ、胸を、貫かれても死ぬことは、ない……あそことは、大違いだ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_deusolbert_1#originalText","id":"talk.vc.home_touch_deusolbert_1","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"你居然想摸光荣的集成骑士的头……真是不知恐惧为何物的家伙。","en":"You dare touch the head of an esteemed Integrity Knight? You...imprudent fool.","ja":"栄えある整合騎士の頭を触ろうとは……恐れを知らぬヤツよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_deusolbert_2#originalText","id":"talk.vc.home_touch_deusolbert_2","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"以前，似乎也有人这样碰触我的脸颊……我有那样的记忆。","en":"Long ago, someone once touched my face like this... Or at least I have a hazy memory of it.","ja":"昔、このように顔に触れた相手がいたような……そんな記憶がある"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_deusolbert_3#originalText","id":"talk.vc.home_touch_deusolbert_3","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"如果你想申请进行模拟战，我随时奉陪。","en":"If you desire a mock-battle, I am always willing.","ja":"模擬戦の申し込みであればいつでも受けよう"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_deusolbert_4#originalText","id":"talk.vc.home_touch_deusolbert_4","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"这副肉体不会老去，也不会衰弱。","en":"My body will never age or waste away.","ja":"この肉体は、老いることも衰えることもない"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_deusolbert_5#originalText","id":"talk.vc.home_touch_deusolbert_5","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"你居然这么轻易地就深入我的怀里……","en":"You dare callously dive into my pockets?","ja":"我が懐に、こうもたやすく潜り込むとは……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_deusolbert_8#originalText","id":"talk.vc.home_touch_deusolbert_8","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"怎么了？你有事拜托我吗？视内容而定，我或许可以答应。","en":"What? Do you have a request for me? I will listen, if it is worthy of my time.","ja":"どうした、我に頼みごとか?内容によっては聞いてやろう"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_diavel_1#originalText","id":"talk.vc.home_touch_diavel_1","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"嘿唷……我可不会那么轻易就让你摸到喔。","en":"Whoa, there. Hands off.","ja":"おっと……そう簡単には触らせないよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_diavel_2#originalText","id":"talk.vc.home_touch_diavel_2","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"你对我的头发有兴趣吗？","en":"Is my hair really that interesting?","ja":"オレの髪に興味があるのかい?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_diavel_3#originalText","id":"talk.vc.home_touch_diavel_3","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"我身上有沾到什么吗？我是已经有在注意了……","en":"Is there something on me? I try to pay attention to that sort of thing.","ja":"なにか付いてるかな?気をつけてるつもりだけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_diavel_4#originalText","id":"talk.vc.home_touch_diavel_4","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"将拳头靠上彼此的胸膛，就有种产生羁绊的感觉对吧！","en":"A fist to the chest gives a real sense of brotherhood!","ja":"お互いの胸に拳を当てるってなんか絆っぽいものを感じるよな!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_diavel_5#originalText","id":"talk.vc.home_touch_diavel_5","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"哈哈，你根本就是冲着我的要害来的嘛。","en":"Haha, look at you, aiming for my vitals.","ja":"はは、オレの急所を的確に狙ってくるじゃないか"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_diavel_8#originalText","id":"talk.vc.home_touch_diavel_8","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"在这个世界，也能感受到心跳吗？","en":"Can you feel heartbeats in this world, too?","ja":"こっちの世界でも、心臓の鼓動は感じるのかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_dil_1#originalText","id":"talk.vc.home_touch_dil_1","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"能得到皇帝陛下的宠爱是我的荣幸。","en":"Receiving his majesty's affection is an honor of the highest order.","ja":"皇帝陛下のご寵愛をいただけるとは光栄の極みでございます"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_dil_2#originalText","id":"talk.vc.home_touch_dil_2","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"请不要随便触碰我。我所准备好的毒和刀刃，可能会伤害到你。","en":"Don't touch it recklessly. The blade and poison that I prepared could make you suffer greatly.","ja":"うかつにお触れになりませんよう仕込んだ毒と刃が、御身をわずらわせるかもしれません"},"kind":"dialogue"}]};
